2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Assets\Concerns;
6	
7	use AtrioTeam\DigitalHub\Assets\Models\AssetFolder;
8	use Illuminate\Database\Eloquent\Relations\MorphMany;
9	use Illuminate\Support\Collection;
10	use Spatie\MediaLibrary\InteractsWithMedia;
11	
12	/**
13	 * Trait per i modelli che possiedono asset (media di spatie/laravel-medialibrary).
14	 *
15	 * IMPORTANTE: il modello che usa questo trait DEVE dichiarare
16	 * `implements \Spatie\MediaLibrary\HasMedia` e
17	 * `\AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets`. Un trait non può
18	 * aggiungere un'interfaccia alla classe — spatie richiede `HasMedia` (è il
19	 * contratto che il media-library cerca), e `OwnsAssets` (soddisfatto dai metodi
20	 * di questo trait) serve a tipizzare il proprietario quando è risolto
21	 * dinamicamente (es. AssetManager via morph).
22	 *
23	 * Configurazione opzionale lato modello (lette via property_exists, niente
24	 * compatibility check tra trait e classe usante — stessa convenzione di
25	 * HasTechnicalAttributes::$attributesColumn):
26	 *
27	 *   protected static string $assetsCollection = 'assets';
28	 *   protected static string $assetsDisk = 'assets';
29	 *
30	 * Senza override, il disco è quello configurato in config('digital-hub.assets_disk')
31	 * (default 'assets'), che il template definisce in config/filesystems.php.
32	 *
33	 * Folder (#15): le folder sono logiche (tabella asset_folders polimorfica,
34	 * adjacency list), non riflesse sul filesystem. Un media appartiene al più a
35	 * una folder (colonna media.asset_folder_id); asset_folder_id null = root.
36	 *
37	 * @mixin \Illuminate\Database\Eloquent\Model
38	 */
39	trait HasAssets
40	{
41	    use InteractsWithMedia;
42	
43	    /**
44	     * Collection di default per gli asset del record. Disk opzionale: se non
45	     * dichiarato, si usa il default di config('media-library.disk_name').
46	     */
47	    public function registerMediaCollections(): void
48	    {
49	        $collection = $this->addMediaCollection($this->assetsCollection());
50	
51	        $disk = $this->assetsDisk();
52	        if ($disk !== null) {
53	            $collection->useDisk($disk);
54	        }
55	    }
56	
57	    public function assetsCollection(): string
58	    {
59	        if (! property_exists(static::class, 'assetsCollection')) {
60	            return 'assets';
61	        }
62	
63	        $collection = static::$assetsCollection;
64	
65	        return is_string($collection) && $collection !== '' ? $collection : 'assets';
66	    }
67	
68	    public function assetsDisk(): ?string
69	    {
70	        if (property_exists(static::class, 'assetsDisk')) {
71	            $disk = static::$assetsDisk;
72	
73	            if (is_string($disk) && $disk !== '') {
74	                return $disk;
75	            }
76	        }
77	
78	        $configured = config('digital-hub.assets_disk');
79	
80	        return is_string($configured) && $configured !== '' ? $configured : null;
81	    }
82	
83	    /**
84	     * Tutte le folder del record (intero albero, ogni livello).
85	     *
86	     * @return MorphMany<AssetFolder, $this>
87	     */
88	    public function assetFolders(): MorphMany
89	    {
90	        return $this->morphMany(AssetFolder::class, 'folderable');
91	    }
92	
93	    /**
94	     * Tutte le folder del record (intero albero), ordinate per sort poi id.
95	     *
96	     * @return \Illuminate\Database\Eloquent\Collection<int, AssetFolder>
97	     */
98	    public function allAssetFolders(): \Illuminate\Database\Eloquent\Collection
99	    {
100	        return $this->assetFolders()
101	            ->orderBy('sort')
102	            ->orderBy('id')
103	            ->get();
104	    }
105	
106	    /**
107	     * Folder di primo livello (parent_id null) del record, ordinate.
108	     *
109	     * @return \Illuminate\Database\Eloquent\Collection<int, AssetFolder>
110	     */
111	    public function rootAssetFolders(): \Illuminate\Database\Eloquent\Collection
112	    {
113	        return $this->assetFolders()
114	            ->whereNull('parent_id')
115	            ->orderBy('sort')
116	            ->get();
117	    }
118	
119	    /**
120	     * Crea una folder per il record, opzionalmente sotto un parent dello stesso
121	     * record. La validazione gerarchia (profondità, owner, cicli) è applicata
122	     * dal model AssetFolder al salvataggio.
123	     */
124	    public function createAssetFolder(string $name, ?AssetFolder $parent = null): AssetFolder
125	    {
126	        $folder = $this->assetFolders()->make([
127	            'name' => $name,
128	            'parent_id' => $parent?->getKey(),
129	        ]);
130	
131	        $folder->save();
132	
133	        return $folder;
134	    }
135	
136	    /**
137	     * Media del record contenuti in una folder (null = root). Filtra sulla
138	     * collection degli asset e sulla folder.
139	     *
140	     * @return Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
141	     */
142	    public function assetsInFolder(?AssetFolder $folder): Collection
143	    {
144	        return $this->media()
145	            ->where('collection_name', $this->assetsCollection())
146	            ->where('asset_folder_id', $folder?->getKey())
147	            ->orderBy('order_column')
148	            ->get();
149	    }
150	}
