3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Assets\Jobs;
6	
7	use AtrioTeam\DigitalHub\Assets\Metadata\ExtractedMetadata;
8	use AtrioTeam\DigitalHub\Assets\Metadata\MetadataExtractionPipeline;
9	use AtrioTeam\DigitalHub\Assets\Support\AssetFileType;
10	use AtrioTeam\DigitalHub\Assets\Support\AssetPreview;
11	use AtrioTeam\DigitalHub\Assets\Support\AssetProcessingStatus;
12	use Illuminate\Bus\Queueable;
13	use Illuminate\Contracts\Queue\ShouldQueue;
14	use Illuminate\Foundation\Bus\Dispatchable;
15	use Illuminate\Queue\InteractsWithQueue;
16	use Illuminate\Queue\SerializesModels;
17	use Illuminate\Support\Facades\Log;
18	use Illuminate\Support\Facades\Storage;
19	use Spatie\MediaLibrary\MediaCollections\Models\Media;
20	use Symfony\Component\Process\Process;
21	use Throwable;
22	
23	/**
24	 * Elaborazione di un asset appena caricato (digital-hub #16/#18).
25	 *
26	 * Estrae i metadati delegando alla {@see MetadataExtractionPipeline} (immagini
27	 * EXIF/IPTC/XMP, PDF, video/audio) e genera l'anteprima; è il punto unico in cui
28	 * faranno casa le elaborazioni future (taglie/conversioni, ...). Porta il media
29	 * da `pending` a `completed`, o a `failed` se l'esecuzione lancia (vedi
30	 * {@see self::failed()}).
31	 *
32	 * Idempotente: ri-eseguibile (sovrascrive i metadati) per retry o riprocesso.
33	 */
34	class ProcessAssetJob implements ShouldQueue
35	{
36	    use Dispatchable;
37	    use InteractsWithQueue;
38	    use Queueable;
39	    use SerializesModels;
40	
41	    /** Channel di log dedicato all'elaborazione asset (registrato dal service provider). */
42	    private const LOG_CHANNEL = 'assets';
43	
44	    public function __construct(public int $mediaId)
45	    {
46	        // dispatch dopo il commit della transazione (rilevante con code reali);
47	        // $afterCommit è definito dal trait Queueable, quindi lo valorizziamo qui
48	        $this->afterCommit = true;
49	
50	        $this->queue = 'assets';
51	    }
52	
53	    public function handle(MetadataExtractionPipeline $pipeline): void
54	    {
55	        $media = $this->findMedia();
56	        if ($media === null) {
57	            return;
58	        }
59	
60	        $this->markStatus($media, AssetProcessingStatus::Processing);
61	
62	        // Estrazione metadati nella colonna `extracted_metadata` (struttura ibrida
63	        // common + verbatim, design §4.7). La pipeline sceglie l'estrattore giusto
64	        // in base al mime; qui resta solo il punto di dispatch.
65	        $this->extractMetadata($media, $pipeline);
66	
67	        // Poster/anteprima (oggi: frame dei video via ffmpeg).
68	        $this->generatePreview($media);
69	
70	        $this->markStatus($media, AssetProcessingStatus::Completed);
71	    }
72	
73	    public function failed(?Throwable $exception): void
74	    {
75	        Log::channel(self::LOG_CHANNEL)->error('Elaborazione asset fallita', [
76	            'media_id' => $this->mediaId,
77	            'exception' => $exception,
78	        ]);
79	
80	        $media = $this->findMedia();
81	        if ($media !== null) {
82	            $this->markStatus($media, AssetProcessingStatus::Failed);
83	        }
84	    }
85	
86	    private function findMedia(): ?Media
87	    {
88	        $media = Media::query()->whereKey($this->mediaId)->first();
89	
90	        return $media instanceof Media ? $media : null;
91	    }
92	
93	    private function markStatus(Media $media, AssetProcessingStatus $status): void
94	    {
95	        $media->setAttribute('processing_status', $status->value);
96	        $media->save();
97	    }
98	
99	    /**
100	     * Estrae i metadati del media e li scrive nella colonna `extracted_metadata`.
101	     * Delega alla pipeline la scelta dell'estrattore (immagini/PDF/video/audio);
102	     * il `common` di base (size/mime/filename) è sempre valorizzato.
103	     */
104	    private function extractMetadata(Media $media, MetadataExtractionPipeline $pipeline): void
105	    {
106	        ExtractedMetadata::write($media, $pipeline->extractFor($media));
107	        $media->save();
108	    }
109	
110	    /**
111	     * Genera il poster/anteprima leggera dell'asset: thumbnail ridimensionato per
112	     * le immagini (GD), frame estratto per i video (ffmpeg), prima pagina per i
113	     * PDF (Ghostscript + GD). Audio → nessun poster (icona). Best-effort:
114	     * errore/strumento assente viene loggato ma NON fa fallire l'asset, che ricade
115	     * sull'originale o sull'icona.
116	     */
117	    private function generatePreview(Media $media): void
118	    {
119	        $type = AssetFileType::fromMedia($media);
120	
121	        try {
122	            if ($type->isImage()) {
123	                $this->generateImageThumbnail($media);
124	            } elseif ($type->isVideo()) {
125	                $this->extractVideoPoster($media);
126	            } elseif ($type->isPdf()) {
127	                $this->generatePdfThumbnail($media);
128	            }
129	        } catch (Throwable $e) {
130	            Log::channel(self::LOG_CHANNEL)->error('Errore durante la generazione anteprima asset', [
131	                'media_id' => $media->getKey(),
132	                'file_name' => $media->getAttribute('file_name'),
133	                'exception' => $e,
134	            ]);
135	            report($e);
136	        }
137	    }
138	
139	    /**
140	     * Thumbnail ottimizzato per un'immagine. Se è già entro il limite non genera
141	     * nulla: in griglia si userà l'originale (già leggero).
142	     */
143	    private function generateImageThumbnail(Media $media): void
144	    {
145	        $source = Storage::disk($media->disk)->get($media->getPathRelativeToRoot());
146	        if (! is_string($source)) {
147	            return;
148	        }
149	
150	        $thumb = $this->thumbnailJpeg($source, skipIfSmall: true);
151	        if ($thumb !== null) {
152	            $this->storePreview($media, $thumb);
153	        }
154	    }
155	
156	    /**
157	     * Thumbnail della prima pagina di un PDF: Ghostscript rasterizza la pagina 1
158	     * (PNG, già motore PDF di riferimento, indipendente dalla policy ImageMagick),
159	     * poi si riusa la pipeline GD per ridurla a thumbnail JPEG.
160	     */
161	    private function generatePdfThumbnail(Media $media): void
162	    {
163	        $source = Storage::disk($media->disk)->get($media->getPathRelativeToRoot());
164	        if (! is_string($source)) {
165	            return;
166	        }
167	
168	        $tmpIn = (string) tempnam(sys_get_temp_dir(), 'asset_pdf_');
169	        $tmpOut = $tmpIn . '.png';
170	
171	        try {
172	            file_put_contents($tmpIn, $source);
173	
174	            $process = new Process([
175	                'gs',
176	                '-dSAFER', '-dBATCH', '-dNOPAUSE', '-dQUIET',
177	                '-sDEVICE=png16m',
178	                '-dFirstPage=1', '-dLastPage=1',
179	                '-r150', '-dUseCropBox',
180	                '-sOutputFile=' . $tmpOut,
181	                $tmpIn,
182	            ]);
183	            $process->setTimeout(60);
184	            $process->run();
185	
186	            if (! $process->isSuccessful() || ! is_file($tmpOut) || filesize($tmpOut) === 0) {
187	                $this->logFailedPreviewTool($media, 'gs', $process);
188	
189	                return; // best-effort: nessun thumbnail, si ricade sull'icona
190	            }
191	
192	            $raster = file_get_contents($tmpOut);
193	            if ($raster === false) {
194	                return;
195	            }
196	
197	            $thumb = $this->thumbnailJpeg($raster, skipIfSmall: false);
198	            if ($thumb !== null) {
199	                $this->storePreview($media, $thumb);
200	            }
201	        } finally {
202	            @unlink($tmpIn);
203	            @unlink($tmpOut);
204	        }
205	    }
206	
207	    /**
208	     * Riduce i byte di un'immagine a un thumbnail JPEG (max 640px lato lungo, q75),
209	     * sfondo bianco per i formati con alpha. Ritorna i byte JPEG o null se non
210	     * decodificabile o — con $skipIfSmall — se è già entro il limite (in tal caso
211	     * il chiamante usa l'originale). Solo downscale: mai upscaling.
212	     */
213	    private function thumbnailJpeg(string $bytes, bool $skipIfSmall): ?string
214	    {
215	        $image = @imagecreatefromstring($bytes);
216	        if ($image === false) {
217	            return null;
218	        }
219	
220	        $max = 640;
221	        $width = imagesx($image);
222	        $height = imagesy($image);
223	
224	        if ($skipIfSmall && $width <= $max && $height <= $max) {
225	            return null;
226	        }
227	
228	        $scale = min(1.0, $max / max($width, $height));
229	        $newW = max(1, (int) round($width * $scale));
230	        $newH = max(1, (int) round($height * $scale));
231	
232	        $thumb = imagecreatetruecolor($newW, $newH);
233	        $white = (int) imagecolorallocate($thumb, 255, 255, 255);
234	        imagefilledrectangle($thumb, 0, 0, $newW, $newH, $white);
235	        imagecopyresampled($thumb, $image, 0, 0, 0, 0, $newW, $newH, $width, $height);
236	
237	        ob_start();
238	        imagejpeg($thumb, null, 75);
239	        $data = (string) ob_get_clean();
240	
241	        return $data === '' ? null : $data;
242	    }
243	
244	    /**
245	     * Estrae un frame del video (~1s) con il binario ffmpeg nativo e lo salva
246	     * come poster sul disco del media. Lavora su file temporanei locali per
247	     * essere indipendente dal tipo di disco.
248	     */
249	    private function extractVideoPoster(Media $media): void
250	    {
251	        $source = Storage::disk($media->disk)->get($media->getPathRelativeToRoot());
252	        if (! is_string($source)) {
253	            return;
254	        }
255	
256	        $tmpIn = (string) tempnam(sys_get_temp_dir(), 'asset_src_');
257	        $tmpOut = $tmpIn . '.jpg';
258	
259	        try {
260	            file_put_contents($tmpIn, $source);
261	
262	            $process = new Process([
263	                'ffmpeg', '-y',
264	                '-ss', '00:00:01',
265	                '-i', $tmpIn,
266	                '-frames:v', '1',
267	                '-vf', "scale='min(640,iw)':-2",
268	                $tmpOut,
269	            ]);
270	            $process->setTimeout(60);
271	            $process->run();
272	
273	            if (! $process->isSuccessful() || ! is_file($tmpOut) || filesize($tmpOut) === 0) {
274	                $this->logFailedPreviewTool($media, 'ffmpeg', $process);
275	
276	                return; // best-effort: nessun poster, si ricade sull'icona
277	            }
278	
279	            $poster = file_get_contents($tmpOut);
280	            if ($poster === false) {
281	                return;
282	            }
283	
284	            $this->storePreview($media, $poster);
285	        } finally {
286	            @unlink($tmpIn);
287	            @unlink($tmpOut);
288	        }
289	    }
290	
291	    /**
292	     * Traccia in log il fallimento di uno strumento esterno di anteprima
293	     * (ffmpeg/Ghostscript): exit code e stderr. Senza questo l'asset resta
294	     * `completed` ma senza preview, e il motivo (codec non supportato, binario
295	     * assente, frame oltre la durata, …) andrebbe perso. Warning, non error: è
296	     * best-effort, l'asset ricade sull'icona.
297	     */
298	    private function logFailedPreviewTool(Media $media, string $tool, Process $process): void
299	    {
300	        Log::channel(self::LOG_CHANNEL)->warning("Anteprima asset non generata: {$tool} non ha prodotto output", [
301	            'media_id' => $media->getKey(),
302	            'file_name' => $media->getAttribute('file_name'),
303	            'exit_code' => $process->getExitCode(),
304	            'stderr' => trim($process->getErrorOutput()),
305	        ]);
306	    }
307	
308	    /**
309	     * Salva i byte del poster/thumbnail nella cartella del media e ne registra il
310	     * path in custom property ({@see AssetPreview}). Writer unico per immagini e video.
311	     */
312	    private function storePreview(Media $media, string $data): void
313	    {
314	        $path = AssetPreview::relativePath($media);
315	        Storage::disk($media->disk)->put($path, $data);
316	
317	        $media->setCustomProperty(AssetPreview::PROPERTY, $path);
318	        $media->save();
319	    }
320	}
