13	/**
14	 * Sostituzione del file fisico di un asset esistente (digital-hub 22i).
15	 *
16	 * Il record `Media` mantiene **lo stesso id** (e uuid/name): folder, tag, share
17	 * e riferimenti dalle entità restano validi senza toccare nulla. Cambiano solo
18	 * il file su disco e gli attributi che lo descrivono (`file_name`, `mime_type`,
19	 * `size`); metadati estratti e anteprima vengono azzerati e rigenerati
20	 * ridispacciando il {@see ProcessAssetJob} (il media torna `pending`).
21	 *
22	 * spatie non ha un "replace" nativo (`addMedia` crea sempre un nuovo record),
23	 * quindi la sostituzione è manuale. Il suo observer però, quando `file_name`
24	 * cambia, rinomina lui il file fisico al salvataggio (`syncFileNames`): va
25	 * quindi salvato PRIMA il record — l'observer sposta il vecchio file sul nuovo
26	 * path — e POI sovrascritto il contenuto (scrivere prima verrebbe sovrascritto
27	 * dalla rinomina). Il path generator usa l'id del media come cartella, per cui
28	 * la cartella su disco resta la stessa.
29	 */
30	final class AssetFileReplacer
31	{
32	    public static function replace(Media $media, UploadedFile $file): void
33	    {
34	        $disk = Storage::disk($media->disk);
35	
36	        // lettura prima di toccare il record: se il temporaneo è illeggibile
37	        // si fallisce qui, col media ancora intatto
38	        $contents = $file->get();
39	        if (! is_string($contents)) {
40	            throw new \RuntimeException('Unreadable uploaded file: ' . $file->getClientOriginalName());
41	        }
42	
43	        $media->file_name = self::sanitizeFileName($file->getClientOriginalName());
44	        $media->mime_type = $file->getMimeType() ?? 'application/octet-stream';
45	        $media->size = (int) $file->getSize();
46	
47	        // il contenuto è nuovo: metadati e anteprima del vecchio file non valgono
48	        // più, li rigenera il job
49	        $media->setAttribute(ExtractedMetadata::COLUMN, null);
50	        $media->forgetCustomProperty(AssetPreview::PROPERTY);
51	        $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
52	        $media->save();
53	
54	        // il file (rinominato dall'observer) esiste ancora col contenuto vecchio:
55	        // lo si sovrascrive con quello nuovo
56	        $disk->put($media->getPathRelativeToRoot(), $contents);
57	
58	        $disk->delete(AssetPreview::relativePath($media));
59	
60	        $key = $media->getKey();
61	        if (is_int($key) || is_string($key)) {
62	            ProcessAssetJob::dispatch((int) $key);
63	        }
64	    }
65	
66	    /**
67	     * Stessa sanitizzazione del default di spatie (FileAdder::defaultSanitizer),
68	     * così i nomi restano coerenti con quelli degli upload normali.
69	     */
70	    private static function sanitizeFileName(string $fileName): string
71	    {
72	        return str_replace(['#', '/', '\\', ' '], '-', $fileName);
73	    }
74	}
