protected function setUp(): void
{
    parent::setUp();

    // registrato normalmente dal boot del DigitalHubPlugin, che nei test
    // Livewire non viene eseguito
    DigitalHubTableMacro::register();
}

public function test_edit_action_saves_category_1_id(): void
{
    $this->actingAs(User::factory()->create());
    Filament::setCurrentPanel('admin');

    $indoor = Category1::create(['name' => ['it' => 'Indoor']]);
    $group = TagGroup::create([
        'name' => ['it' => 'Tag Tessuti', 'en' => 'Fabric tags'],
        'entity_type' => 'fabric',
        'target' => TagTarget::Entity,
    ]);

    Livewire::test(ListTagGroups::class)
        ->callTableAction('edit', $group, data: [
            'category_1_id' => $indoor->id,
        ])
        ->assertHasNoTableActionErrors();

    $this->assertSame($indoor->id, $group->refresh()->category_1_id);
    $this->assertTrue($group->category1->is($indoor));
}

public function test_edit_action_allows_clearing_category_1_id(): void
{
    $this->actingAs(User::factory()->create());
    Filament::setCurrentPanel('admin');

    $indoor = Category1::create(['name' => ['it' => 'Indoor']]);
    $group = TagGroup::create([
        'name' => ['it' => 'Tag Tessuti', 'en' => 'Fabric tags'],
        'entity_type' => 'fabric',
        'target' => TagTarget::Entity,
        'category_1_id' => $indoor->id,
    ]);

    Livewire::test(ListTagGroups::class)
        ->callTableAction('edit', $group, data: [
            'category_1_id' => null,
        ])
        ->assertHasNoTableActionErrors();

